    out = [row[:] for row in grid]
    fours = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    sixes = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    if not fours or not sixes:
        return out
    r0, r1 = min(r for r, c in fours), max(r for r, c in fours)
    c0, c1 = min(c for r, c in fours), max(c for r, c in fours)
    mr0, mr1 = min(r for r, c in sixes), max(r for r, c in sixes)
    mc0, mc1 = min(c for r, c in sixes), max(c for r, c in sixes)
    for r, c in sixes:
        out[r][c] = 0
    # Direction of the 6 marker's stem relative to its bar selects the copy side.
    rows = {r: [c for rr, c in sixes if rr == r] for r, c in sixes}
    widest_row = max(rows, key=lambda r: len(set(rows[r])))
    stem_above = mr0 < widest_row
    stem_below = mr1 > widest_row
    if stem_above and not stem_below:
        # Copy left of the 4 object by reflecting across its left boundary.
        for r, c in fours:
            cc = 2*c0 - 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif stem_below and not stem_above:
        # Copy right.
        for r, c in fours:
            cc = 2*c1 + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif mr0 > r1:
        # Copy down.
        for r, c in fours:
            rr = 2*r1 + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        # Copy upward.
        for r, c in fours:
            rr = 2*r0 - 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    return out
